/**
 * Minimal TONE3000 API v1 client (https://www.tone3000.com/api).
 *
 * Authentication (keys are generated by the user at https://www.tone3000.com/settings):
 *   - TONE3000_CLIENT_ID (publishable key): OAuth device flow. The user approves a code in the
 *     browser; access/refresh tokens are stored in TONE3000_TOKEN_FILE and refreshed automatically.
 *   - TONE3000_API_KEY (secret key, t3k_cs_...): sent directly as a Bearer token.
 * The device flow is preferred: model downloads are documented for user access tokens.
 */
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, extname } from "node:path";

const BASE = "https://www.tone3000.com/api/v1";

interface StoredTokens {
  access_token: string;
  refresh_token?: string;
  expires_at: number; // epoch ms
}

export interface Tone3000Config {
  clientId?: string;
  apiKey?: string;
  tokenFile: string;
  /** JSON file with { "tone3000ClientId"?, "tone3000ApiKey"? } saved by tone3000_set_credentials. */
  configFile: string;
}

export const TONE3000_SETTINGS_URL = "https://www.tone3000.com/settings";

/** Thrown when no credentials exist; the server reacts by opening the settings page. */
export class MissingCredentialsError extends Error {}
/** Thrown when a client id exists but there is no valid session; the server starts the device login. */
export class LoginRequiredError extends Error {}

export interface SearchParams {
  query?: string;
  page?: number;
  pageSize?: number;
  sort?: "best-match" | "newest" | "oldest" | "trending" | "downloads-all-time";
  gears?: string[];
  sizes?: string[];
  tags?: string[];
  makes?: string[];
  creators?: string[];
  format?: "nam" | "ir" | "aida-x" | "aa-snapshot" | "proteus";
  architecture?: "1" | "2" | "custom";
  calibrated?: boolean;
  verified?: boolean;
}

export interface PendingDeviceLogin {
  device_code: string;
  user_code: string;
  verification_uri: string;
  verification_uri_complete?: string;
  expires_in: number;
  interval: number;
  started_at: number;
}

export class Tone3000Client {
  private pending?: PendingDeviceLogin;

  constructor(private readonly cfg: Tone3000Config) {
    const saved = this.readConfig();
    this.cfg.clientId ??= saved.tone3000ClientId;
    this.cfg.apiKey ??= saved.tone3000ApiKey;
  }

  private readConfig(): { tone3000ClientId?: string; tone3000ApiKey?: string } {
    try {
      return JSON.parse(readFileSync(this.cfg.configFile, "utf8"));
    } catch {
      return {};
    }
  }

  /** Save credentials given by the user (kept on this machine only). */
  setCredentials(c: { clientId?: string; apiKey?: string }) {
    if (c.apiKey !== undefined && !/^t3k_cs_[A-Za-z0-9_-]+$/.test(c.apiKey)) throw new Error("The secret key should start with t3k_cs_");
    if (c.clientId !== undefined && !/^[A-Za-z0-9_.:-]{8,200}$/.test(c.clientId)) throw new Error("That does not look like a TONE3000 publishable key");
    const saved = { ...this.readConfig() };
    if (c.clientId !== undefined) saved.tone3000ClientId = c.clientId;
    if (c.apiKey !== undefined) saved.tone3000ApiKey = c.apiKey;
    mkdirSync(dirname(this.cfg.configFile), { recursive: true });
    writeFileSync(this.cfg.configFile, JSON.stringify(saved, null, 2), { mode: 0o600 });
    if (c.clientId !== undefined) this.cfg.clientId = c.clientId;
    if (c.apiKey !== undefined) this.cfg.apiKey = c.apiKey;
  }

  get authMode(): "device-flow" | "secret-key" | "none" {
    if (this.cfg.apiKey) return "secret-key";
    if (this.cfg.clientId) return "device-flow";
    return "none";
  }

  get loggedIn(): boolean {
    if (this.cfg.apiKey) return true;
    const t = this.readTokens();
    return !!t && (Date.now() < t.expires_at - 60000 || !!t.refresh_token);
  }

  private readTokens(): StoredTokens | undefined {
    if (!existsSync(this.cfg.tokenFile)) return undefined;
    try {
      return JSON.parse(readFileSync(this.cfg.tokenFile, "utf8"));
    } catch {
      return undefined;
    }
  }

  private saveTokens(t: { access_token: string; refresh_token?: string; expires_in?: number }) {
    mkdirSync(dirname(this.cfg.tokenFile), { recursive: true });
    const stored: StoredTokens = {
      access_token: t.access_token,
      refresh_token: t.refresh_token,
      expires_at: Date.now() + (t.expires_in ?? 3600) * 1000,
    };
    writeFileSync(this.cfg.tokenFile, JSON.stringify(stored, null, 2), { mode: 0o600 });
  }

  private async form(path: string, body: Record<string, string>) {
    const res = await fetch(`${BASE}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
      body: new URLSearchParams(body).toString(),
    });
    const json: any = await res.json().catch(() => ({}));
    return { ok: res.ok, status: res.status, json };
  }

  /** Step 1 of the device flow: returns a code the user approves at tone3000.com/activate. */
  async startDeviceLogin(): Promise<PendingDeviceLogin> {
    if (!this.cfg.clientId) throw new MissingCredentialsError("No TONE3000 publishable key yet.");
    const r = await this.form("/oauth/device_authorization", { client_id: this.cfg.clientId, scope: "read" });
    if (!r.ok) throw new Error(`TONE3000 device authorization failed (${r.status}): ${JSON.stringify(r.json)}`);
    this.pending = { ...r.json, started_at: Date.now() };
    return this.pending!;
  }

  /** Step 2: poll until the user approved (or the code expired). */
  async finishDeviceLogin(maxWaitMs = 60000): Promise<{ status: string }> {
    if (!this.pending) throw new LoginRequiredError("No login in progress.");
    const p = this.pending;
    const deadline = Math.min(Date.now() + maxWaitMs, p.started_at + p.expires_in * 1000);
    let interval = Math.max(1, p.interval) * 1000;
    while (Date.now() < deadline) {
      const r = await this.form("/oauth/token", {
        grant_type: "urn:ietf:params:oauth:grant-type:device_code",
        device_code: p.device_code,
        client_id: this.cfg.clientId!,
      });
      if (r.ok && r.json.access_token) {
        this.saveTokens(r.json);
        this.pending = undefined;
        return { status: "logged-in" };
      }
      const err = r.json?.error;
      if (err === "authorization_pending") {
        await new Promise((res) => setTimeout(res, interval));
        continue;
      }
      if (err === "slow_down") {
        interval += 5000;
        await new Promise((res) => setTimeout(res, interval));
        continue;
      }
      this.pending = undefined;
      throw new Error(`TONE3000 login failed: ${err ?? r.status}`);
    }
    return { status: "pending (approve the code in the browser, then call tone3000_login_finish again)" };
  }

  private async bearer(): Promise<string> {
    if (this.cfg.apiKey) return this.cfg.apiKey;
    const t = this.readTokens();
    if (!t) {
      if (!this.cfg.clientId) throw new MissingCredentialsError("No TONE3000 credentials yet.");
      throw new LoginRequiredError("Not logged in to TONE3000.");
    }
    if (Date.now() < t.expires_at - 60000) return t.access_token;
    if (!t.refresh_token || !this.cfg.clientId) throw new LoginRequiredError("TONE3000 session expired.");
    const r = await this.form("/oauth/token", { grant_type: "refresh_token", refresh_token: t.refresh_token, client_id: this.cfg.clientId });
    if (!r.ok) throw new LoginRequiredError("TONE3000 session expired.");
    this.saveTokens(r.json);
    return r.json.access_token;
  }

  async get(path: string, params: Record<string, string | number | boolean | undefined> = {}): Promise<any> {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== "") qs.set(k, String(v));
    const url = `${BASE}${path}${qs.size ? `?${qs}` : ""}`;
    const res = await fetch(url, { headers: { Authorization: `Bearer ${await this.bearer()}`, Accept: "application/json" } });
    if (res.status === 429) throw new Error("TONE3000 rate limit reached (100 requests/minute). Try again shortly.");
    if (!res.ok) throw new Error(`TONE3000 ${path} failed (${res.status}): ${(await res.text()).slice(0, 300)}`);
    return res.json();
  }

  search(p: SearchParams) {
    return this.get("/tones/search", {
      query: p.query,
      page: p.page,
      page_size: p.pageSize,
      sort: p.sort,
      gears: p.gears?.join("_"),
      sizes: p.sizes?.join("_"),
      tags: p.tags?.join("_"),
      makes: p.makes?.join("_"),
      creators: p.creators?.join(","),
      format: p.format,
      architecture: p.architecture,
      calibrated: p.calibrated,
      verified: p.verified,
    });
  }

  getTone(id: number, architecture: "1" | "2" | "custom" = "2") {
    return this.get(`/tones/${id}`, { architecture });
  }

  listModels(toneId: number, architecture: "1" | "2" | "custom" = "2", page = 1, pageSize = 100) {
    return this.get("/models", { tone_id: toneId, architecture, page, page_size: pageSize });
  }

  getModel(id: number) {
    return this.get(`/models/${id}`);
  }

  /** Download a model/IR file. Returns the saved path. */
  async downloadModel(modelId: number, dir: string): Promise<{ path: string; model: any }> {
    const model = await this.getModel(modelId);
    if (!model?.model_url) throw new Error(`Model ${modelId} has no model_url`);
    const res = await fetch(model.model_url, { headers: { Authorization: `Bearer ${await this.bearer()}` } });
    if (!res.ok) throw new Error(`Download failed (${res.status}) for model ${modelId}`);
    const buf = Buffer.from(await res.arrayBuffer());
    let ext = extname(new URL(model.model_url).pathname).toLowerCase();
    if (![".nam", ".wav"].includes(ext)) ext = buf.subarray(0, 4).toString("ascii") === "RIFF" ? ".wav" : ".nam";
    const safe = String(model.name ?? `model-${modelId}`).replace(/[<>:"/\\|?*\x00-\x1f]/g, "_").slice(0, 120);
    mkdirSync(dir, { recursive: true });
    const path = join(dir, `${safe} [t3k-${modelId}]${ext}`);
    writeFileSync(path, buf);
    return { path, model };
  }
}

/** Compact a tone for tool output. */
export function summarizeTone(t: any) {
  return {
    id: t.id,
    title: t.title,
    creator: t.user?.username,
    gear: t.gear,
    format: t.format,
    makes: t.makes?.map((m: any) => m.name ?? m),
    tags: t.tags?.map((m: any) => m.name ?? m),
    sizes: t.sizes,
    a2Models: t.a2_models_count,
    irs: t.irs_count,
    downloads: t.downloads_count,
    favorites: t.favorites_count,
    url: t.url,
  };
}
